	uri->fragment = NULL;
    }
    URL = xmlSaveUri(uri);
    xmlFreeURI(uri);
    if (URL == NULL) {
	xmlXIncludeErrMemory(ctxt);
	if (fragment != NULL)
	    xmlFree(fragment);
        xmlFree(URI);
